SELECT COUNT(*)
FROM STORE_FILE
WHERE STORE_NO = #{storeNo}

SELECT FILE_NO, FILE_PATH, FILE_NAME
FROM STORE_FILE
WHERE FILE_NO = #{fileNo}

SELECT FILE_NO, STORE_NO, FILE_PATH, FILE_NAME, ORIGIN_NAME, IS_MAIN
FROM STORE_FILE
WHERE FILE_NO = #{fileNo}

mapper.update:
UPDATE STORE_FILE
SET IS_MAIN = 'N'
WHERE STORE_NO = #{storeNo}

UPDATE STORE_FILE
SET IS_MAIN = 'Y'
WHERE FILE_NO = #{fileNo}

UPDATE STORE_DETAIL
SET
	SUB_TITLE = #{subTitle},
	S_CONTENTS = #{sContents}
WHERE STORE_NO = #{storeNo}

UPDATE STORE_USER
SET
	CEO_NAME = #{sName}
WHERE S_USER_ID = #{sUserId}
